package org.marketreview.nativeapp;
import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import java.io.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.json.*;
/** Root invokes on device with a NEW cache subdirectory named candidate-background-v40-*. No production paths. */
public final class HostCandidateBackgroundChecks {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}interface Call{void run()throws Exception;}static void rejects(Call action,String why)throws Exception{boolean failed=false;try{action.run();}catch(Exception e){failed=true;}check(failed,why);}
 static void seed(File business,File recent,File leaders,JSONObject input)throws Exception{JSONObject sources=input.getJSONObject("sources");try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(business,null)){db.execSQL("CREATE TABLE records(kind TEXT,id TEXT,payload TEXT,PRIMARY KEY(kind,id))");for(String kind:new String[]{"accounts","trades"}){JSONArray rows=sources.getJSONObject("holdings").getJSONObject("data").getJSONArray(kind);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);ContentValues v=new ContentValues();v.put("kind",kind);v.put("id",row.getString("id"));v.put("payload",row.toString());check(db.insertOrThrow("records",null,v)!=-1,"fixture business");}}}
  try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(recent,null)){db.execSQL("PRAGMA application_id=1381188401");db.execSQL("CREATE TABLE recent_entries(id TEXT PRIMARY KEY,payload TEXT NOT NULL)");JSONArray rows=sources.getJSONObject("recent").getJSONObject("data").getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",row.getString("id"));v.put("payload",row.toString());check(db.insertOrThrow("recent_entries",null,v)!=-1,"fixture recent");}}
  try(SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(leaders,null)){db.execSQL("PRAGMA application_id=1397511729");db.execSQL("CREATE TABLE config(id INTEGER PRIMARY KEY,revision INTEGER,digest TEXT,payload BLOB)");JSONObject config=sources.getJSONObject("leaders").getJSONObject("data");byte[] bytes=config.toString().getBytes(StandardCharsets.UTF_8);ContentValues v=new ContentValues();v.put("id",1);v.put("revision",config.getLong("revision"));v.put("digest",SectorLeaderModel.hash(bytes));v.put("payload",bytes);check(db.insertOrThrow("config",null,v)!=-1,"fixture leaders");}
 }
 public static JSONObject verifyQtBundle(JSONObject bundle)throws Exception{HostCandidateBackground.verify(bundle,null);return new JSONObject().put("passed",true).put("nativeFrameworkBundleHash",HostCandidateBackground.digest(bundle));}
 public static JSONObject run(File isolatedRoot,JSONObject sourceFixture,JSONArray selected)throws Exception{
  checks=0;check(isolatedRoot.getName().startsWith("candidate-background-v40-")&&!isolatedRoot.exists()&&isolatedRoot.mkdirs(),"new isolated directory required");File business=new File(isolatedRoot,"business.sqlite"),recent=new File(isolatedRoot,"recent.sqlite"),leaders=new File(isolatedRoot,"leaders.sqlite"),evidence=new File(isolatedRoot,"evidence.sqlite");seed(business,recent,leaders,sourceFixture);Instant cut=Instant.parse(sourceFixture.getString("capturedAt"));HostCandidateBackground.Hooks stable=new HostCandidateBackground.Hooks(){public Instant now(){return cut;}public void betweenReads(){}};HostCandidateBackground host=new HostCandidateBackground(business,recent,leaders,evidence,stable);check(host.accounts(null).length()==1,"ledger-only explicit choices");JSONObject snapshot=BusinessStore.readLedgerSnapshot(business,null);check(snapshot.has("accounts")&&snapshot.has("trades"),"same transaction ledger API");File absent=new File(isolatedRoot,"absent.sqlite");rejects(()->BusinessStore.readLedgerSnapshot(absent,null),"missing source rejected");check(!absent.exists(),"missing source never initialized");
  JSONObject bundle=host.capture(selected,"stable",Arrays.asList("account-A"),null);HostCandidateBackground.verify(bundle,null);JSONObject bg=bundle.getJSONObject("adapter").getJSONObject("backgrounds").getJSONObject("SH:stock:600001");check("known".equals(bg.getJSONObject("holdings").getString("status"))&&"known".equals(bg.getJSONObject("recent").getString("status"))&&"known".equals(bg.getJSONObject("leaders").getString("status")),"actual source projection");check("unknown".equals(bg.getJSONObject("themes").getString("status")),"themes remain unknown");rejects(()->host.capture(selected,"stable",Collections.emptyList(),null),"scope must be explicit");check(host.head(null).isEmpty()&&!evidence.exists(),"head read creates nothing");String first=host.putDraft(bundle,"",null);check(HostCandidateBackground.digest(host.readDraft(first,null)).equals(HostCandidateBackground.digest(bundle)),"atomic adapter+result draft");String id=host.save("设备隔离背景记录",bundle,cut,null);check(host.list(null).length()==1,"named evidence retained");JSONObject next=host.capture(selected,"breakout",Arrays.asList("account-A"),null);String second=host.putDraft(next,first,null);rejects(()->host.putDraft(bundle,first,null),"stale draft CAS");rejects(()->host.readDraft(first,null),"old anchor must not redirect");rejects(()->host.putDraft(bundle,second,()->true),"cancelled write");check(host.head(null).equals(second),"newer draft survives reject/cancel");java.util.concurrent.atomic.AtomicBoolean cancelled=new java.util.concurrent.atomic.AtomicBoolean();HostCandidateBackground.Hooks rollback=new HostCandidateBackground.Hooks(){public Instant now(){return cut;}public void betweenReads(){}public void beforeCommit(){cancelled.set(true);}};rejects(()->new HostCandidateBackground(business,recent,leaders,evidence,rollback).putDraft(bundle,second,cancelled::get),"precommit cancellation rolls back pair");check(host.head(null).equals(second),"rollback leaves prior complete draft");rejects(()->new HostCandidateBackground(business,recent,leaders,business).putDraft(bundle,"",null),"evidence cannot target source database");
  HostCandidateBackground replay=new HostCandidateBackground(absent,absent,absent,evidence);check(HostCandidateBackground.digest(replay.read(id,null).getJSONObject("bundle")).equals(HostCandidateBackground.digest(bundle)),"history replay without live sources");HostCandidateBackground.Hooks changed=new HostCandidateBackground.Hooks(){public Instant now(){return cut;}public void betweenReads(){try(SQLiteDatabase db=SQLiteDatabase.openDatabase(business.getPath(),null,SQLiteDatabase.OPEN_READWRITE)){db.execSQL("UPDATE records SET payload=replace(payload,'账本字段样例','已变更') WHERE kind='accounts'");}}};rejects(()->new HostCandidateBackground(business,recent,leaders,evidence,changed).capture(selected,"stable",Arrays.asList("account-A"),null),"source changes reject entire capture");rejects(()->host.remove(id,"stale",null),"history delete CAS");host.remove(id,HostCandidateBackground.digest(bundle),null);check(host.list(null).length()==0,"explicit delete");JSONObject out=new JSONObject().put("passed",true).put("checks",checks).put("sdk",android.os.Build.VERSION.SDK_INT).put("scope","Explicit isolated Android SQLite bridge run; screen/native Main interaction is separate");try(FileOutputStream file=new FileOutputStream(new File(isolatedRoot,"device-check-result.json"))){file.write(out.toString(2).getBytes(StandardCharsets.UTF_8));}return out;
 }
}
